// Screens for Farfisa V: the wave the drawn tabs add up to, and the tremolo's swing.
const BLUE = "#3d7dff", GREEN = "#3ec96b", WHITE = "#ffffff", ORANGE = "#ff6a1a", RED = "#ff3b30", GREY = "#6b6b6b";
const FONT = "8px ui-monospace, monospace";

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const num = (v, d) => (typeof v === "number" && isFinite(v) ? v : d);
const on = (params, name) => num(params[name], 0) >= 0.5;
const last = (arr) => (Array.isArray(arr) && arr.length ? num(arr[arr.length - 1], 0) : 0);

function glass(ctx, W, H) {
  ctx.fillStyle = "#000";
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 1;
  ctx.font = FONT;
  ctx.textBaseline = "top";
}

// One family's waveform at phase p (cycles): strings a saw, flute a sine, oboe and trumpet narrowing pulses.
function voice(kind, p, bright) {
  const x = p - Math.floor(p);
  if (kind === "flute") return Math.sin(x * Math.PI * 2);
  if (kind === "strings") return 1 - 2 * x;
  const w = kind === "oboe" ? 0.3 : 0.15 - bright * 0.05;
  return x < w ? 1 : -w / (1 - w);
}

const STOPS = [
  ["Strings 16", "strings", 0.5, WHITE],
  ["Strings 8", "strings", 1, WHITE],
  ["Strings 4", "strings", 2, WHITE],
  ["Flute 8", "flute", 1, BLUE],
  ["Flute 4", "flute", 2, BLUE],
  ["Oboe 8", "oboe", 1, GREEN],
  ["Trumpet 8", "trumpet", 1, ORANGE],
  ["2-2/3", "flute", 3, BLUE],
];
const FEET = [["16", 0.5], ["8", 1], ["4", 2], ["2⅔", 3]];

export default {
  voices(lcd) {
    const { ctx, width: W, height: H, params } = lcd;
    glass(ctx, W, H);
    const bright = on(params, "Brilliant") ? 1 : 0;
    const live = STOPS.filter(([name]) => on(params, name));
    const legend = 14, top = 4, bottom = H - legend - 2;
    const mid = (top + bottom) / 2, amp = Math.max(4, (bottom - top) / 2 - 2);
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    ctx.moveTo(4, mid);
    ctx.lineTo(W - 4, mid);
    ctx.stroke();
    // One cycle of the 16' pitch, so every footage fits a whole number of turns.
    const n = Math.max(2, Math.floor(W - 8));
    const ys = [];
    let peak = 0;
    for (let i = 0; i <= n; i++) {
      let y = 0;
      for (const [, kind, m] of live) y += voice(kind, (i / n) * m, bright);
      ys.push(y);
      peak = Math.max(peak, Math.abs(y));
    }
    const vib = on(params, "Vibrato On/Off") ? (num(params["Vibrato Depth"], 0) >= 0.5 ? 2 : 1) : 0;
    ctx.strokeStyle = WHITE;
    ctx.beginPath();
    for (let i = 0; i <= n; i++) {
      const wob = vib ? Math.sin((i / n) * Math.PI * 6) * vib : 0;
      const y = mid - (peak > 0 ? ys[i] / peak : 0) * amp;
      if (i === 0) ctx.moveTo(4 + i + wob, y);
      else ctx.lineTo(4 + i + wob, y);
    }
    ctx.stroke();
    // The footage strip: one column per foot, a dot per family drawn on it.
    const cw = (W - 8) / FEET.length;
    FEET.forEach(([label, m], c) => {
      const x = 4 + c * cw;
      ctx.fillStyle = GREY;
      ctx.fillText(label + "'", x, H - legend + 3);
      let k = 0;
      for (const [name, , mm, col] of STOPS) {
        if (mm !== m) continue;
        ctx.fillStyle = on(params, name) ? col : "#222";
        ctx.fillRect(x + 22 + k * 7, H - legend + 4, 5, 5);
        k++;
      }
    });
    if (!live.length) {
      ctx.fillStyle = GREY;
      ctx.fillText("NO TABS", 6, top + 2);
    }
    if (on(params, "Bass On/Off")) {
      ctx.fillStyle = BLUE;
      ctx.fillText("BASS", W - 30, top + 2);
    }
  },

  trem_wave(lcd) {
    const { ctx, width: W, height: H, params, output } = lcd;
    glass(ctx, W, H);
    const active = on(params, "Tremolo On/Off");
    const rate = clamp(num(params["Tremolo Rate"], 0.33), 0, 1);
    const sync = on(params, "Tremolo Sync");
    const mid = H / 2, amp = H * 0.38;
    const cycles = 1 + rate * 7;
    const lvl = clamp(0.4 + last(output) * 2, 0.4, 1);
    const n = Math.max(2, Math.floor(W - 8));
    // The envelope the tremolo cuts: a sine of its rate, or flat when it is off.
    const gain = (t) => (active ? 0.55 + 0.45 * Math.sin(t * cycles * Math.PI * 2) : 1);
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    for (let i = 0; i <= n; i++) {
      const t = i / n, y = Math.sin(t * Math.PI * 2 * 40) * gain(t) * amp * lvl;
      if (i === 0) ctx.moveTo(4 + i, mid - y);
      else ctx.lineTo(4 + i, mid - y);
    }
    ctx.stroke();
    ctx.strokeStyle = active ? GREEN : GREY;
    for (const s of [1, -1]) {
      ctx.beginPath();
      for (let i = 0; i <= n; i++) {
        const y = mid - s * gain(i / n) * amp * lvl;
        if (i === 0) ctx.moveTo(4 + i, y);
        else ctx.lineTo(4 + i, y);
      }
      ctx.stroke();
    }
    ctx.fillStyle = active ? GREEN : GREY;
    ctx.fillText(active ? (sync ? "TREM SYNC" : "TREM") : "TREM OFF", 4, 3);
    if (typeof params["Amp Power"] === "number" && !on(params, "Amp Power")) {
      ctx.fillStyle = RED;
      ctx.fillText("AMP OFF", Math.max(4, W - 40), 3);
    }
  },
};

// vox-continental-v2 screen: the wave the two manuals' footage drawbars add up to, and each drawbar's partial.
const BLUE = "#3d7dff", GREEN = "#3ec96b", WHITE = "#ffffff", ORANGE = "#ff6a1a", GREY = "#6b6b6b";
const FONT = "8px ui-monospace, monospace";
// Each drawbar's pitch as a multiple of the 8' fundamental: 16', 8', 4', 2 2/3', 2', 1 3/5', 1 1/3', 1'.
const RATIO = [0.5, 1, 2, 3, 4, 5, 6, 8];

function text(ctx, s, x, y, c, align) {
  ctx.fillStyle = c;
  ctx.font = FONT;
  ctx.textAlign = align || "left";
  ctx.fillText(s, x, y);
}

function levels(p, manual) {
  const out = [];
  for (let i = 1; i <= 8; i++) out.push(Math.max(0, Math.min(1, p[`${manual} Ft ${i}`] ?? 1)));
  return out;
}

// A flute is a sine, a reed a square: the voice blend shapes every partial alike.
function sample(lv, ph, flute, reed) {
  let s = 0;
  for (let i = 0; i < 8; i++) {
    if (lv[i] <= 0) continue;
    const a = 2 * Math.PI * ph * RATIO[i];
    s += lv[i] * (flute * Math.sin(a) + reed * (Math.sin(a) >= 0 ? 0.7 : -0.7));
  }
  return s;
}

function plot(ctx, lv, flute, reed, x, y, w, h, col) {
  let max = 1e-6;
  const n = Math.max(2, Math.floor(w));
  const ys = [];
  for (let i = 0; i <= n; i++) {
    const v = sample(lv, (i / n) * 2, flute, reed);
    ys.push(v);
    max = Math.max(max, Math.abs(v));
  }
  ctx.strokeStyle = col;
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 0; i <= n; i++) {
    const px = x + (i / n) * w, py = y + h / 2 - (ys[i] / max) * (h / 2);
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.stroke();
}

export default {
  organ_screen(lcd) {
    const { ctx, width: W, height: H, params: p, now } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    const up = levels(p, "Upper"), lo = levels(p, "Lower");
    const uf = p["Upper Flute"] ?? 1, ur = p["Upper Reed"] ?? 1;
    const lf = p["Lower Flute"] ?? 1, lr = p["Lower Reed"] ?? 1;
    const swell = p["Swell Pedal"] ?? 1;
    const vib = (p["Vibrato On/Off"] ?? 0) >= 0.5;
    const split = W * 0.55;
    const wy = 14, wh = H - 24;
    const wob = vib ? Math.sin(((now || 0) / 1000) * (2 + (p["Vibrato Rate"] ?? 0.7) * 6)) * (p["Vibrato Depth"] ?? 0.5) * 2 : 0;
    plot(ctx, lo, lf, lr, 4, wy + wh * 0.5, split - 8, wh * 0.45 * swell, GREEN);
    plot(ctx, up, uf, ur, 4 + wob, wy, split - 8, wh * 0.5 * swell, BLUE);
    text(ctx, "UPPER", 4, 9, BLUE);
    text(ctx, "LOWER", 40, 9, GREEN);
    ctx.fillStyle = "#1a1a1a";
    ctx.fillRect(split, 4, 1, H - 8);
    const bx = split + 6, bw = W - bx - 4, base = H - 12, top = 14;
    const slot = bw / 8;
    for (let i = 0; i < 8; i++) {
      const x = bx + i * slot;
      const hu = (base - top) * up[i], hl = (base - top) * lo[i];
      ctx.fillStyle = up[i] > 0.01 ? BLUE : GREY;
      ctx.fillRect(x, base - Math.max(1, hu), Math.max(2, slot * 0.4), Math.max(1, hu));
      ctx.fillStyle = lo[i] > 0.01 ? GREEN : GREY;
      ctx.fillRect(x + slot * 0.45, base - Math.max(1, hl), Math.max(2, slot * 0.4), Math.max(1, hl));
      const perc = i < 4 && (p[`Perc Ft ${i + 1}`] ?? 0) >= 0.5;
      if (perc) { ctx.fillStyle = ORANGE; ctx.fillRect(x, top - 4, Math.max(2, slot * 0.85), 2); }
    }
    text(ctx, (p["Engine"] ?? 0) >= 0.5 ? "JENNINGS" : "VOX", W - 4, 9, WHITE, "right");
    text(ctx, "16'", bx, H - 2, GREY);
    text(ctx, "1'", W - 4, H - 2, GREY, "right");
  },
};
